	CONSTRAINT "counter_sales_buyer_name_length" CHECK (char_length(btrim("counter_sales"."buyer_name")) between 2 and 120 and "counter_sales"."buyer_name" = btrim("counter_sales"."buyer_name")),
	CONSTRAINT "counter_sales_buyer_phone_format" CHECK ("counter_sales"."buyer_phone" ~ '^\+?[0-9][0-9 -]{5,18}[0-9]$')
);
