-- Whoever reads customers may know which one is the walk-in customer.
CREATE POLICY walk_in_customers_select ON public.walk_in_customers FOR SELECT TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor', 'sales_manager', 'salesperson', 'recovery_officer')
  );
