-- A counter sale is seen by whoever may see its order: the order's own rules decide.
CREATE POLICY counter_sales_select ON public.counter_sales FOR SELECT TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND EXISTS (SELECT 1 FROM public.sales_documents d WHERE d.tenant_id = counter_sales.tenant_id AND d.id = counter_sales.order_id)
  );
