-- ── hand-written: the walk-in customer ──────────────────────────────────────────────────────────
-- The company's walk-in customer, made the first time it is asked for. Two counter sales that
-- both find none take turns, and the second finds the first one's.
CREATE FUNCTION app.walk_in_customer() RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_customer uuid;
  v_name text := 'Walk-in customer';
  v_try integer := 1;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant') THEN
    RAISE EXCEPTION 'this role does not sell at the counter' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT w.customer_id INTO v_customer FROM public.walk_in_customers w WHERE w.tenant_id = v_tenant;
  IF FOUND THEN
    RETURN v_customer;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('walk-in:' || v_tenant::text, 0));
  SELECT w.customer_id INTO v_customer FROM public.walk_in_customers w WHERE w.tenant_id = v_tenant;
  IF FOUND THEN
    RETURN v_customer;
  END IF;
  -- A customer of that name already on the list is someone else's: the walk-in customer takes the next free name.
  WHILE EXISTS (SELECT 1 FROM public.customers c WHERE c.tenant_id = v_tenant AND lower(c.name) = lower(v_name)) LOOP
    v_try := v_try + 1;
    v_name := 'Walk-in customer ' || v_try;
  END LOOP;
  INSERT INTO public.customers (tenant_id, name, registration_type, credit_days, created_by, updated_by)
    VALUES (v_tenant, v_name, 'unregistered', 0, v_user, v_user)
    RETURNING id INTO v_customer;
  INSERT INTO public.walk_in_customers (tenant_id, customer_id, created_by) VALUES (v_tenant, v_customer, v_user);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'customer.create', 'customer', v_customer, jsonb_build_object('name', v_name, 'walkIn', true));
  RETURN v_customer;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.walk_in_customer() FROM PUBLIC;
--> statement-breakpoint
