--> statement-breakpoint

-- ── hand-written: a counter sale is written once ────────────────────────────────────────────────
-- Made with a draft order to the walk-in customer; then its invoice (made from that order, still a
-- draft) and its receipt (a cash or bank draft from the walk-in customer) are named, once each.
-- Nothing else about it ever changes, and it is never removed.
CREATE FUNCTION app.check_counter_sale() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_customer uuid;
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'a counter sale is never removed' USING ERRCODE = 'SE123';
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT w.customer_id INTO v_customer FROM public.walk_in_customers w WHERE w.tenant_id = NEW.tenant_id;
  IF TG_OP = 'INSERT' THEN
    NEW.created_by := app.current_user_id();
    NEW.created_at := now();
    IF NEW.invoice_id IS NOT NULL OR NEW.receipt_id IS NOT NULL THEN
      RAISE EXCEPTION 'a counter sale starts with its order alone' USING ERRCODE = 'SE123';
    END IF;
    IF v_customer IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.sales_documents d
      WHERE d.tenant_id = NEW.tenant_id AND d.id = NEW.order_id AND d.kind = 'order' AND d.status = 'draft' AND d.customer_id = v_customer
    ) THEN
      RAISE EXCEPTION 'a counter sale is made with a draft order to the walk-in customer' USING ERRCODE = 'SE122';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.id <> OLD.id OR NEW.tenant_id <> OLD.tenant_id OR NEW.order_id <> OLD.order_id OR NEW.buyer_name <> OLD.buyer_name
     OR NEW.buyer_phone IS DISTINCT FROM OLD.buyer_phone OR NEW.created_at <> OLD.created_at OR NEW.created_by <> OLD.created_by
     OR (OLD.invoice_id IS NOT NULL AND NEW.invoice_id IS DISTINCT FROM OLD.invoice_id)
     OR (OLD.receipt_id IS NOT NULL AND NEW.receipt_id IS DISTINCT FROM OLD.receipt_id)
     OR (NEW.receipt_id IS NOT NULL AND NEW.invoice_id IS NULL) THEN
    RAISE EXCEPTION 'a counter sale names its invoice and its receipt once, and nothing else about it changes' USING ERRCODE = 'SE123';
  END IF;
  IF OLD.invoice_id IS NULL AND NEW.invoice_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.sales_documents i
    WHERE i.tenant_id = NEW.tenant_id AND i.id = NEW.invoice_id AND i.kind = 'invoice' AND i.status = 'draft' AND i.source_document_id = NEW.order_id
  ) THEN
    RAISE EXCEPTION 'a counter sale''s invoice is a draft made from its order' USING ERRCODE = 'SE122';
  END IF;
  IF OLD.receipt_id IS NULL AND NEW.receipt_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.receipts r
    WHERE r.tenant_id = NEW.tenant_id AND r.id = NEW.receipt_id AND r.status = 'draft' AND r.customer_id = v_customer AND r.method IN ('cash', 'bank')
  ) THEN
    RAISE EXCEPTION 'a counter sale''s receipt is a cash or bank draft from the walk-in customer' USING ERRCODE = 'SE122';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_counter_sale() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER counter_sales_check
  BEFORE INSERT OR UPDATE OR DELETE ON public.counter_sales
  FOR EACH ROW EXECUTE FUNCTION app.check_counter_sale();
--> statement-breakpoint

-- ── hand-written: the walk-in customer is sold to only at the counter ───────────────────────────
-- Runs after sales_documents_check (triggers of the same kind fire in the order of their names),
-- which has by then copied the buyer from the customer as a document is submitted: for a counter
-- sale the buyer is the one typed at the counter.
CREATE FUNCTION app.check_walk_in_document() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_counter public.counter_sales%ROWTYPE;
BEGIN
  IF session_user = 'postgres' THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.walk_in_customers w WHERE w.tenant_id = NEW.tenant_id AND w.customer_id = NEW.customer_id) THEN
    RETURN NEW;
  END IF;
  IF NEW.kind IN ('quotation', 'delivery') THEN
    RAISE EXCEPTION 'the walk-in customer is sold to only at the counter' USING ERRCODE = 'SE122';
  END IF;
  IF NEW.kind = 'order' THEN
    -- Its counter sale is written after the draft; it must be there by the time the order is submitted.
    IF NEW.status <> 'draft' AND (TG_OP = 'INSERT' OR OLD.status = 'draft' OR OLD.status = 'on_hold') THEN
      SELECT c.* INTO v_counter FROM public.counter_sales c WHERE c.tenant_id = NEW.tenant_id AND c.order_id = NEW.id;
      IF NOT FOUND OR NEW.status <> 'submitted' THEN
        RAISE EXCEPTION 'the walk-in customer is sold to only at the counter, and pays at once' USING ERRCODE = 'SE122';
      END IF;
      NEW.buyer_name := v_counter.buyer_name;
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.kind = 'invoice' THEN
    SELECT c.* INTO v_counter FROM public.counter_sales c WHERE c.tenant_id = NEW.tenant_id AND c.order_id = NEW.source_document_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'the walk-in customer is sold to only at the counter, and pays at once' USING ERRCODE = 'SE122';
    END IF;
    IF NEW.status = 'submitted' AND (TG_OP = 'INSERT' OR OLD.status = 'draft') THEN
      NEW.buyer_name := v_counter.buyer_name;
    END IF;
    RETURN NEW;
  END IF;
  -- A credit note names the buyer its invoice named.
  IF NEW.kind = 'credit_note' AND NEW.status = 'submitted' AND (TG_OP = 'INSERT' OR OLD.status = 'draft') THEN
    SELECT c.* INTO v_counter FROM public.counter_sales c
      JOIN public.sales_documents i ON i.tenant_id = c.tenant_id AND i.source_document_id = c.order_id
      WHERE i.tenant_id = NEW.tenant_id AND i.id = NEW.source_document_id AND i.kind = 'invoice';
    IF FOUND THEN
      NEW.buyer_name := v_counter.buyer_name;
    END IF;
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_walk_in_document() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER sales_documents_walk_in
  BEFORE INSERT OR UPDATE ON public.sales_documents
  FOR EACH ROW EXECUTE FUNCTION app.check_walk_in_document();
--> statement-breakpoint

-- ── hand-written: a walk-in buyer pays at once ──────────────────────────────────────────────────
-- Money from the walk-in customer is the counter sale's own receipt: cash or bank, never a
-- cheque, and posted only as paying the counter sale's invoice in full.
CREATE FUNCTION app.check_walk_in_receipt() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_counter public.counter_sales%ROWTYPE;
BEGIN
  IF session_user = 'postgres' THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.walk_in_customers w WHERE w.tenant_id = NEW.tenant_id AND w.customer_id = NEW.customer_id) THEN
    RETURN NEW;
  END IF;
  IF NEW.method NOT IN ('cash', 'bank') THEN
    RAISE EXCEPTION 'a walk-in buyer pays in cash or into a bank account' USING ERRCODE = 'SE122';
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'draft' AND NEW.status <> 'draft' THEN
    SELECT c.* INTO v_counter FROM public.counter_sales c WHERE c.tenant_id = NEW.tenant_id AND c.receipt_id = NEW.id;
    IF NOT FOUND OR v_counter.invoice_id IS NULL
       OR (SELECT count(*) FROM public.receipt_allocations a WHERE a.tenant_id = NEW.tenant_id AND a.receipt_id = NEW.id) <> 1
       OR NOT EXISTS (
         SELECT 1 FROM public.receipt_allocations a
         WHERE a.tenant_id = NEW.tenant_id AND a.receipt_id = NEW.id AND a.invoice_id = v_counter.invoice_id AND a.amount = NEW.amount
       ) THEN
      RAISE EXCEPTION 'money from the walk-in customer is a counter sale''s receipt, paying its invoice in full' USING ERRCODE = 'SE122';
    END IF;
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_walk_in_receipt() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER receipts_walk_in
  BEFORE INSERT OR UPDATE ON public.receipts
  FOR EACH ROW EXECUTE FUNCTION app.check_walk_in_receipt();
